/**
 * bridge.ts — DSH 侧桥绑定（spawn 适配 + 诊断挂钩，薄壳）。
 *
 * 2026-09-15 电话机上移：NDJSON 协议机（行缓冲/请求应答配对/超时/优雅停机/
 * 事件上抛/B5 失败上报）唯一活在 femo2host/host/bridge-client.mjs——zcode 的
 * bridge-manager.mjs 已是它的第一个绑定，本文件是第二个。只剩 DSH 特有的三件：
 *  ① spawn 走 dsh subprocess 服务（服务未就绪轮询等待 30s + python 可执行解析）；
 *  ② SubprocessHandle → BridgeChild 契约适配（done promise → 'exit' 事件）；
 *  ③ 诊断挂钩（撕裂行取证/引擎 print 透传 → 诊断流 + Host 页口径直写 stdout）。
 * 对外接口（FemoBridge/start(ctx,config)/send/stop/alive/onExited/sendActorFailure）
 * 与原版完全一致——index.ts/engine-events/routes/tools 零改动。
 */

import type { Context } from '@deepseek-ai/cordis'
import type { SubprocessHandle } from '@deepseek-ai/dsh-subprocess'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { pushDiag } from './diag-feed'
import { BridgeClient, sendActorFailure, type BridgeChild } from '../../../femo2host/host/bridge-client.mjs'

export { sendActorFailure }

/** 宿主自称：读本地能力清单（host.manifest.json）的 `host` 字段——'dsh' / 'zcode'。
 *  它就是投影中心的**来源标签**（多宿主共演同一场时，行/段键/信任集都按它分
 *  命名空间，2026-09-19 联机改造）。读不到就空串，hub 退回单来源老行为。
 *  桥侧从同一份清单读（femoCompiler/host_manifest.py 的 host_name()），
 *  宿主侧把同一个名字放进 env，两边报出来的必须是同一个词。 */
function hostNameOf(manifestFile: string): string {
  try {
    const data = JSON.parse(readFileSync(manifestFile, 'utf8')) as { host?: unknown }
    const h = typeof data.host === 'string' ? data.host.trim() : ''
    return h
  } catch {
    return ''
  }
}

/** SubprocessHandle → 桥电话机要的子进程外形：done promise 翻译成 'exit'
 *  事件；terminate 翻译成 kill；exitCode 用本地标记同步暴露（handle 本体
 *  无同步 exitCode——stop() 的「已退出就不再等」判定靠它）。 */
function wrapDshHandle(handle: SubprocessHandle): BridgeChild {
  let exited = false
  let code: number | null = null
  void handle.done.then((outcome: unknown) => {
    exited = true
    code = (outcome as { exitCode?: number } | undefined)?.exitCode ?? -1
  }, () => {
    exited = true
    code = -1
  })
  const fireExit = (cb: (code: number | null, signal: string | null) => void): void => {
    void handle.done.then((outcome: unknown) => {
      cb((outcome as { exitCode?: number } | undefined)?.exitCode ?? -1, null)
    }, () => cb(-1, null))
  }
  return {
    stdout: handle.stdout as unknown as BridgeChild['stdout'],
    stderr: handle.stderr as unknown as BridgeChild['stderr'],
    stdin: handle.stdin as unknown as BridgeChild['stdin'],
    on: ((event: string, cb: never) => {
      if (event === 'exit') fireExit(cb as unknown as (code: number | null, signal: string | null) => void)
      return handle
    }) as unknown as BridgeChild['on'],
    once: ((event: string, cb: never) => {
      if (event === 'exit') fireExit(cb as unknown as (code: number | null, signal: string | null) => void)
      return handle
    }) as unknown as BridgeChild['once'],
    pid: handle.pid,
    kill: () => { try { handle.terminate() } catch { /* 已退出则忽略 */ } },
    get exitCode() { return exited ? (code ?? -1) : null },
  } as BridgeChild
}

export class FemoBridge extends BridgeClient {
  /** 驿站投递员上门端口（index.ts 起好收件口后注入；undefined=自取模式）。
   *  经 spawn env（FEMO_PUSH_PORT）交给桥侧 mail_courier。 */
  pushPort?: number

  constructor() {
    super({
      // start(ctx, config) 备齐 spawn 三要素（argv/cwd/env + 已解析的
      // python）后才真正调用——构造期的占位不该被触发。
      spawnProc: () => { throw new Error('bridge spawn not prepared (start() must run first)') },
      // index.ts 事后注入 emit（(bridge as any).emit = ...）——延迟解引用。
      onEvent: (eventType, data) => {
        pushDiag('bridge', `event ${eventType} job=${String((data as Record<string, unknown> | undefined)?.job_id ?? '-')}`)
        ;(this as unknown as { emit?: (name: string, ...args: unknown[]) => void }).emit?.('femo-plugin/event', eventType, data)
      },
      // 【Host 页口径 2026-09-11】引擎 print/stderr 是"引擎的话"：绕过 console
      // 直写 stdout（harness 日志照收），同时全量进诊断流『编译器』页。
      onEngineLine: line => {
        // 【诊断 2026-09-06】撕裂嫌疑：NDJSON 事件行若被引擎 print 的并发
        // write 粘包/撕裂，首字符不再是 '{' 且行内必含 JSON 事件字段——
        // 此类行是"human_wait 事件在管道中丢失"假设的直接证据。
        if (line.includes('"type"') || line.includes('job_id')) {
          pushDiag('bridge', `TORN_LINE_SUSPECT: ${line.slice(0, 300)}`)
        }
        pushDiag('engine', line.slice(0, 400))
        process.stdout.write(`[femo-engine] ${line}\n`)
      },
      onEngineStderr: line => {
        pushDiag('engine', `[stderr] ${line}`.slice(0, 400))
        process.stdout.write(`[femo-engine:stderr] ${line}\n`)
      },
      onParseFail: line => { pushDiag('bridge', `JSON_PARSE_FAIL: ${line.slice(0, 300)}`) },
      log: msg => console.log(`[femo-plugin] ${msg}`),
    })
  }

  /** Spawn the bridge and wire stdout line parsing（原签名不变；参数可选是为
   *  兼容基类 BridgeClient.start() 的空参形状——内部两参齐备才走 DSH 装配）。
   *  插件树并发装配：本插件 apply 可能先于 base bundle 的 subprocess
   *  provider 完成（rc.2 快照插件更多、apply 更慢，固定 1s 延迟不再够）。
   *  轮询等待而不是一次性放弃——最多 30s。 */
  start(ctx?: Context, config?: { python: string; femoRoot: string; hostManifest: string }, attempt = 0): void {
    if (this.alive) return
    if (ctx === undefined || config === undefined) {
      super.start()
      return
    }
    const subprocess = ctx.get('subprocess') as {
      resolveExecutable(command: string, env?: Record<string, string>, signal?: AbortSignal): Promise<string>
      spawn(spec: unknown): SubprocessHandle
    } | undefined
    if (subprocess === undefined) {
      if (attempt < 30) {
        setTimeout(() => this.start(ctx, config, attempt + 1), 1000)
        return
      }
      console.log('[femo-plugin] subprocess service unavailable after 30s; bridge not started')
      return
    }
    if (attempt > 0) console.log(`[femo-plugin] subprocess service ready after ${attempt}s wait; starting bridge`)
    // 宿主自称（清单 host 字段）：写进本进程 env，hub-feed 按同一个词报来源；
    // 同时随 env 传给桥（桥再注册给 hub）。两处必须是同一个词，否则同一台机器的
    // 桥喂的行与宿主喂的行会在账本里被当成两个来源（2026-09-19 联机改造）。
    const hostName = hostNameOf(config.hostManifest)
    if (hostName !== '') process.env.FEMO_HOST_NAME = hostName
    // 桥本体已上移共享层（2026-09-15）：<femoRoot>/femo2host/python/femo_bridge.py。
    // 宿主能力清单（A2.1 解耦）随适配器本地（config.hostManifest）。
    this.argv = [
      join(config.femoRoot, 'femo2host', 'python', 'femo_bridge.py'),
      '--fe4m', config.femoRoot,
      '--host-manifest', config.hostManifest,
    ]
    this.cwd = config.femoRoot
    // FEMO_PUSH_PORT：驿站投递员的上门地址（system_push 模式开关——缺省
    // 不带，桥侧 mail_courier 自动留柜自取，zcode/旧宿主行为不变）。
    // FEMO_HOST_NAME：宿主自称（清单 host 字段）——桥拿去注册给投影 hub；本进程
    // 的 hub-feed 也从这里读同一个词（两边报出来的来源标签必须一致，否则同一台
    // 机器的「桥喂的行」和「宿主喂的行」在账本里会被当成两个来源）。
    this.env = {
      PYTHONIOENCODING: 'utf-8', PYTHONUTF8: '1',
      ...(this.pushPort !== undefined ? { FEMO_PUSH_PORT: String(this.pushPort) } : {}),
      ...(hostName !== '' ? { FEMO_HOST_NAME: hostName } : {}),
    }
    void subprocess.resolveExecutable(config.python).then((pythonPath) => {
      this.spawnProc = (spec) => wrapDshHandle(subprocess.spawn({
        argv: [pythonPath, ...spec.argv],
        cwd: spec.cwd,
        stdio: {
          stdin: 'pipe',
          stdout: 'pipe',
          // 'pipe' (not collect): the caller owns the stream and forwards
          // tracebacks live; a collect buffer would swallow them silently.
          stderr: 'pipe',
        },
        graceMs: 3000,
        env: spec.env,
      }))
      super.start()
    }, (error: unknown) => {
      console.log(`[femo-plugin] python resolve failed: ${String(error)}`)
    })
  }
}
