/**
 * mailbox-push.ts — 驿站投递员的上门收件口（who_move=system_push 的 dsh 端）。
 *
 * 2026-09-16 上门投递落地：桥侧 mail_courier 在产信现场把信直推进本接收口
 * （先投后发事件——时序契约见 mail_courier.py 文件头）。收件即办、回执即账：
 *  · main 料包信（kind=context + brief 面单）→ 登记节点视野 →
 *    runMainModelTurn 拼词上场（交付队列等机制照旧）；
 *  · 演员料包信（2026-09-17 对齐主模型，soul=该演员）→ dispatchActorTurn
 *    steer 到对应子代理窗口（soul↔子代理的对应由派工函数内的常驻执行体
 *    注册表承担）；
 *  · 人类等待信（2026-09-17，无 source 的 context 信）→ applyHumanWait 显示
 *    给人类看（投影窗等待；与 AI 拍同一封信，呈现不同）；
 *  · 终局整包（notice 信 + outcome）→ 公共拼词（notice-core）→ steerMainAgent
 *    直达主模型对话流。
 *  · 开演/续跑信（2026-09-23 十连裁④，notice 信 subkind=play_start）→
 *    steerMainAgent 直达主模型（画布点开演/断点续跑时 main 知情）。
 *  · 人类插话信（2026-09-23 十连裁⑨，notice 信 subkind=user_interjection +
 *    extra.interjection.mainSid）→ followupMain 以真人消息直达主模型
 *    （source=user 渲染气泡；桥侧投递失败即死信，宿主已降级直推）。
 *  · 重试牌信（2026-09-23 十连裁③，notice 信 subkind=node_retry +
 *    extra.retry 面单）→ broker.deliverRetry 按 wait_key 交停靠经纪人
 *    （信是唯一传话通道，事件侧已停消费）。
 * 【2026-09-23 十连裁②⑩ 单通道】查簿兜底已废：push 是唯一通道，一次产信恰
 * 一次投递，事件侧纯记账；送失的信由投递员重投（mail_courier.retry_pending，
 * mailbox.pending_urgent 年龄门槛防产信窗口双投）——邮差扑空修邮差。
 *
 * 物理形态：femo-plugin 自管的迷你监听器（127.0.0.1，FEMO_PUSH_PORT 缺省
 * 3895 起顺延扫描——dsh webServer 端口插件侧拿不到，自管监听器端口确定、
 * 经 spawn env 交给桥）。只服务本机桥进程，与 zcode gateway 同级信任。
 */

import type { Context } from '@deepseek-ai/cordis'
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http'
import { SessionId, type Session } from '@deepseek-ai/dsh-session'
import type { FemoBridge } from './bridge'
import { sendActorFailure } from './bridge'
import type { ResolvedConfig } from './config'
import { readBody, writeJson } from './http'
import type { RunState } from './engine-events'
import { followupMain, steerMainAgent, dispatchActorTurn, applyHumanWait } from './engine-events'
import { broker } from './node-retry'
import type { ProjectionRegistry } from './projection'
import { runMainModelTurn, noteMainActor } from './main-actor'
import { formatStopNotice, type NoticeLetter, type StopOutcome } from '../../../femo2host/host/notice-core.mjs'
import { actorNameOf } from './actor-name'   // 执行者名的唯一取值口

export interface MailboxPushDeps {
  resolved: ResolvedConfig
  bridge: FemoBridge
  runState: RunState
  projections: ProjectionRegistry
  sessionsStore?: { get(id: SessionId): Session | undefined }
  /** 演员派工（dispatchActorTurn）要吃的默认模型选择器（index 总装现成）。 */
  defaultModel?: { currentSelection(): unknown }
  recordError(sessionId: SessionId, text: string): void
}

/** POST /femo-plugin/mailbox-push 的收件处理（先登记簿后回执——回执即账）。 */
async function handlePush(ctx: Context, deps: MailboxPushDeps, body: Record<string, unknown>): Promise<void> {
  const { resolved, bridge, runState, projections, sessionsStore, defaultModel, recordError } = deps
  const letters = Array.isArray(body.letters) ? body.letters as NoticeLetter[] : []
  const outcome = typeof body.outcome === 'string' ? body.outcome : undefined

  // ── 终局整包（bridge 侧 extra 带 outcome）──────────────────────────────
  if (outcome !== undefined) {
    const jobIdRaw = letters.length > 0 ? letters[0].job_id : undefined
    const jobId = typeof body.job_id === 'number' ? body.job_id
      : typeof jobIdRaw === 'number' ? jobIdRaw : undefined
    if (jobId === undefined || (outcome !== 'finished' && outcome !== 'failed' && outcome !== 'paused')) {
      console.log(`[femo-plugin] mailbox-push: bad stop pack (outcome=${outcome}, jobId=${String(jobId)})`)
      return
    }
    // 回执即账（单通道无簿）：终局信由桥产信+投递员整包直推，此处只开嗓。
    const mirror = runState.jobs.get(jobId)
    if (mirror === undefined) {
      console.log(`[femo-plugin] mailbox-push: stop pack for unknown job ${jobId} (letters dropped)`)
      return
    }
    const detail = typeof body.detail === 'string' ? body.detail : undefined
    steerMainAgent(ctx, mirror.ownerSid, formatStopNotice({
      jobId, outcome: outcome as StopOutcome, ...(detail !== undefined ? { detail } : {}), letters,
    }))
    return
  }

  // ── 开演/续跑信（2026-09-23 十连裁④：notice 信 subkind=play_start）─────
  // flow_start 现场产信给 main（urgent 单封直推）：画布点开演、断点续跑时
  // main 未必知情。收信即 steer 通知全文；一次开演恰一封，无兜底双路故不去重。
  const playLetter = letters.find(x => x !== null && typeof x === 'object'
    && x.kind === 'notice' && x.subkind === 'play_start')
  if (playLetter !== undefined) {
    const jobId = typeof playLetter.job_id === 'number' ? playLetter.job_id : undefined
    const mirror = jobId === undefined ? undefined : runState.jobs.get(jobId)
    if (mirror === undefined) {
      console.log(`[femo-plugin] mailbox-push: play_start letter without mirror (job=${String(jobId)})`)
      return
    }
    steerMainAgent(ctx, mirror.ownerSid, String(playLetter.payload ?? ''))
    return
  }

  // ── 重试牌信（2026-09-23 十连裁③：notice 信 subkind=node_retry）────────
  // feedback 点对点内容改寄驿站：收信按 wait_key 交停靠经纪人（租约保留
  // 超时/中止；事件侧不再消费——信是唯一传话通道）。主模型/演员/人类三种
  // 停靠者由经纪人按 parker kind 分发，信无需区分。
  const retryPack = body.retry as { wait_key?: unknown; feedback?: unknown; attempt?: unknown; actor_name?: unknown } | undefined
  const retryLetter = letters.find(x => x !== null && typeof x === 'object'
    && x.kind === 'notice' && x.subkind === 'node_retry')
  if (retryPack !== undefined && retryLetter !== undefined) {
    const waitKey = String(retryPack.wait_key ?? '')
    if (waitKey.length === 0) {
      console.log('[femo-plugin] mailbox-push: node_retry without wait_key (dropped)')
      return
    }
    broker.deliverRetry(waitKey, String(retryPack.feedback ?? ''),
      Number(retryPack.attempt ?? 1) || 1, String(retryPack.actor_name ?? ''))
    return
  }

  // ── 人类插话信（2026-09-23 十连裁⑨：notice 信 subkind=user_interjection）──
  // 投影窗上帝窗戏外发言寄驿站（单通道）：source=user 的真人标记由 followup
  // 保住（渲染=用户气泡非系统注入，绝不走 plugin steer）；mainSid 由产信侧
  // push extra 带回。桥侧投递失败即死信+宿主降级直推，故此处无降级职责。
  const interjection = body.interjection as { mainSid?: unknown } | undefined
  const interLetter = letters.find(x => x !== null && typeof x === 'object'
    && x.kind === 'notice' && x.subkind === 'user_interjection')
  if (interjection !== undefined && interLetter !== undefined) {
    const mainSid = typeof interjection.mainSid === 'string' ? interjection.mainSid : ''
    if (mainSid.length === 0) {
      console.log('[femo-plugin] mailbox-push: user interjection without mainSid (dropped)')
      return
    }
    followupMain(ctx, mainSid, String(interLetter.payload ?? ''))
    return
  }

  // ── 料包信（bridge 侧 extra 带 brief 面单；一份解析三路分流）───────────
  // 信到驿站时人类拍与 AI 拍同构（compiler 索回信，ref=wait_key）；分流只看
  // 面单 source：'main'=主模型上场、其他值=演员 steer、无 source=人类等待
  // （呈现=投影窗显示，非 steer）——收信后的差别是宿主的事，驿站只管投递。
  // 【十连裁② 单通道】无簿无兜底：一封信一次投递，事件侧纯记账。
  const brief = body.brief as Record<string, unknown> | undefined
  const letter = letters.find(x => x !== null && typeof x === 'object' && x.kind === 'context')
  if (brief === undefined || letter === undefined) return
  const ref = String(brief.wait_key ?? letter.ref ?? '')
  const jobIdRaw = letter.job_id
  const jobId = typeof jobIdRaw === 'number' ? jobIdRaw : -1
  if (ref.length === 0) {
    console.log('[femo-plugin] mailbox-push: brief without wait_key (dropped)')
    return
  }
  const mirror = runState.jobs.get(jobId)
  if (mirror === undefined) {
    console.log(`[femo-plugin] mailbox-push: brief for unknown job ${jobId} (ref=${ref.slice(0, 24)})`)
    return
  }
  const session = sessionsStore?.get(SessionId(mirror.ownerSid))
  if (session === undefined) {
    // 【十连裁② 单通道】事件兜底已废：此处漏拍无兜底可救（信已回执清账，
    // 重投看不到它）——大声留痕，引擎 3600s 等待超时是最后的安全网。
    recordError(SessionId(mirror.ownerSid), '驿站信件无法投递：主会话不在 store（宿主重启窄窗口）')
    console.log(`[femo-plugin] mailbox-push: session ${mirror.ownerSid} not in store; no fallback since 单通道 (2026-09-23)`)
    return
  }

  if (String(brief.source ?? '') === 'main') {
    // 主模型上场：登记节点视野 → runMainModelTurn（交付队列照旧；单通道无簿）。
    const nodeName = typeof brief.node_name === 'string' ? brief.node_name : undefined
    const scopeInfo = Array.isArray(brief.scope_info)
      ? brief.scope_info.filter((x): x is string => typeof x === 'string')
      : undefined
    if (nodeName !== undefined && scopeInfo !== undefined) mirror.nodeScopes.set(nodeName, scopeInfo)
    noteMainActor(mirror.ownerSid, actorNameOf(brief))
    void runMainModelTurn(ctx, resolved, bridge, session, brief, recordError, projections, mirror.nodeScopes, mirror.nodeShowprompts, jobId)
      .catch((error: unknown) => {
        recordError(session.id, `主模型下场注入失败：${String(error)}`)
        void sendActorFailure(bridge, jobId, ref, 'main_executor_error', String(error)).catch(() => undefined)
      })
    return
  }

  if (brief.source !== undefined) {
    // 演员料包（soul=该角色）：收信即 steer 到对应子代理窗口——唯一派工体
    // （dispatchActorTurn）。
    dispatchActorTurn(ctx, resolved, bridge, session, brief, recordError, defaultModel, mirror, projections, jobId)
    return
  }

  // 人类等待信（无 source=非 AI 轮）→ applyHumanWait（快照+广播+租约）——
  // 与演员同一封信，宿主呈现改成显示给人看。
  applyHumanWait(ctx, runState, session, projections, broker, mirror, brief)
}

/**
 * 起投递员上门收件口。返回实际监听端口（桥经 spawn env 拿到）；端口全部被占
 * 或 HTTP 不可用 → undefined（桥收不到 FEMO_PUSH_PORT → 自动留柜自取模式，
 * 既有 collect/事件兜底链路完整兜住——降级不断戏）。
 */
export async function startMailboxPushListener(ctx: Context, deps: MailboxPushDeps): Promise<{ port: number } | undefined> {
  const basePort = Number(process.env.FEMO_PUSH_PORT ?? '3895')
  for (let attempt = 0; attempt < 20; attempt++) {
    const port = basePort + attempt
    const server = createServer((req: IncomingMessage, res: ServerResponse) => {
      const url = new URL(req.url ?? '/', 'http://127.0.0.1')
      if (url.pathname !== '/femo-plugin/mailbox-push' || req.method !== 'POST') {
        writeJson(res, 404, { ok: false, error: 'not found' })
        return
      }
      void readBody(req).then(body => {
        return handlePush(ctx, deps, (body ?? {}) as Record<string, unknown>)
      }).then(() => {
        writeJson(res, 200, { ok: true })
      }).catch((error: unknown) => {
        console.log(`[femo-plugin] mailbox-push handler failed: ${String(error instanceof Error ? error.message : error)}`)
        writeJson(res, 200, { ok: true })  // 处理失败也回执：信已消费，账记 push 已送达
      })
    })
    const ok = await new Promise<boolean>(resolve => {
      server.once('error', () => resolve(false))
      server.listen(port, '127.0.0.1', () => resolve(true))
    })
    if (!ok) continue
    console.log(`[femo-plugin] mailbox push listener: http://127.0.0.1:${port}/femo-plugin/mailbox-push`)
    ctx.effect(() => () => { server.close() }, 'femo-plugin: mailbox push listener')
    return { port }
  }
  console.log(`[femo-plugin] mailbox push listener: no free port from ${basePort}; courier falls back to pickup mode`)
  return undefined
}
